def transform(grid):
    """Reflect each input row horizontally and concatenate; stack
    vertically in reverse, forward, reverse row order."""
    out = []
    for rows in (grid[::-1], grid, grid[::-1]):
        for row in rows:
            out.append(row[::-1] + row)
    return out
